def inert_source(extra=b''):
    """Wholly decoded inert file subset; never a vendor-qualified project."""
    app=b'[Application]\r\n'+b''.join(line(k,v) for k,v in dict(Version='6.6.2.48',NewVersion='6.6.2.48',PanelSeries='DOP-100 series',PanelName='Synthetic',ModelName=268502788,PanelResWidth=800,PanelResHeight=480,DefaultScreen=1,InitialMacroLen=0,ClockMacroLen=0).items())
    first=b'[Screen]\r\nID=1\r\n'+wide('wTextLen','First')+b'PictureOffset=0\r\nBgColor=0\r\n[AuxKeyElement]\r\n'
    label=b'[Element]\r\nnPartsID=10\r\nType=10\r\nSubType=6\r\nX=1\r\nY=1\r\nWidth=100\r\nHeight=20\r\nReadVar=None\r\nWriteVar=None\r\nTriggerVar=None\r\nBeforeExecMacroLen=0\r\n'+extra+wide('wDescTextLen0','Label')+b'[State]\r\nValue=0\r\n'+wide('wTextLen0','Label')
    second=b'[Screen]\r\nID=2\r\n'+wide('wTextLen','Second')+b'PictureOffset=0\r\nBgColor=0\r\n[AuxKeyElement]\r\n'
    raw=wrap(app+first+label+second);_,p=fixture();p.update(indexed_layout_sha256=layout_digest(Project(raw)),reviewed_resources=dict(reviewed_boundary_ack=True,source_payload_sha256=sha(Project(raw).file.payload),frames=[]));p.pop('background_sha256')
    return raw,p


class RiskTests(unittest.TestCase):
    def setUp(self):
        self.tmp=tempfile.TemporaryDirectory();self.addCleanup(self.tmp.cleanup);self.root=Path(self.tmp.name)
    def refusal(self,code,fn):
        with self.assertRaises(Exception) as cm:fn()
        self.assertEqual(getattr(cm.exception,'code',None),code,str(cm.exception))
    def session(self,raw=None,profile=None,path='source.dpa'):
        if raw is None:raw,profile=neutral_fixture()
        p=self.root/path
        if not p.exists():p.write_bytes(raw)
        s=Service(self.root,allow_write=True);s.open_project(path,sha(raw),profile,sha(canonical(profile)));s.inspect();return s
    def test_shared_deletion_has_narrow_positive_and_opaque_negative(self):
        raw,p=inert_source();q=Project(raw)
        changed,_=compile_changes(raw,[dict(op='delete_screen',page_id=2)],p);self.assertEqual(len(Project(changed).pages),1)
        spec=dict(version=1,operations=[dict(op='delete_element',page_id=1,element_id=10,expected_element_sha256=element_hash(q,q.element(1,10)))])
        changed=tx.build(raw,p,spec)['candidate'];self.assertEqual(len(Project(changed).page(1).elements),0)
        raw,p=fixture();q=Project(raw)
        self.refusal('DELETE_DEPENDENCY',lambda:compile_changes(raw,[dict(op='delete_screen',page_id=2)],p))
        self.refusal('DELETE_DEPENDENCY',lambda:compile_changes(raw,[dict(op='delete_element',page_id=1,element_id=13)],p))
        self.refusal('DELETE_DEPENDENCY',lambda:tx.build(raw,p,dict(version=1,operations=[dict(op='delete_element',page_id=1,element_id=13,expected_element_sha256=element_hash(q,q.element(1,13)))])))
    def test_deletion_rejects_event_unknown_scalar_and_group_reference_in_both_paths(self):
        for extra in (b'EventID=77\r\n',b'rPartID=0\r\n',b'UnknownWidgetPartID=10\r\n',b'UnknownScript=anything\r\n'):
            with self.subTest(extra=extra):
                raw,p=inert_source(extra);q=Project(raw)
                for op in (dict(op='delete_screen',page_id=2),dict(op='delete_element',page_id=1,element_id=10)):
                    self.refusal('DELETE_DEPENDENCY',lambda:compile_changes(raw,[op],p))
                self.refusal('DELETE_DEPENDENCY',lambda:tx.build(raw,p,dict(version=1,operations=[dict(op='delete_element',page_id=1,element_id=10,expected_element_sha256=element_hash(q,q.element(1,10)))])))
    def test_global_and_page_macros_prevent_page_and_element_deletion(self):
        raw,p=inert_source();q=Project(raw);blob=MacroProgram((MacroInstruction(bytes.fromhex('0000005c'),(b'ELSE',b'',b'',b'',b'')),)).to_bytes()
        for old,new in ((b'InitialMacroLen=0\r\n',line('InitialMacroLen',len(blob))+blob),(b'PictureOffset=0\r\n',line('OpenMacroLen',len(blob))+blob+b'PictureOffset=0\r\n')):
            data=q.file.encode(q.file.payload.replace(old,new,1));fp=deepcopy(p);fp['indexed_layout_sha256']=layout_digest(Project(data));fp['reviewed_resources']['source_payload_sha256']=sha(Project(data).file.payload)
            self.refusal('DELETE_DEPENDENCY',lambda:compile_changes(data,[dict(op='delete_screen',page_id=2)],fp))
            self.refusal('DELETE_DEPENDENCY',lambda:compile_changes(data,[dict(op='delete_element',page_id=1,element_id=10)],fp))
    def test_foreground_shortcut_does_not_flatten_seven_fill_owners(self):
        raw,p=fixture();q=Project(raw);e=q.element(1,10);fields=['FgFillColor','FgFillEndColor',*['FgFillStopColor'+str(i) for i in range(5)]]
        edits=[token_patch(q,e.states[0],k,101+i,'distinct neutral fill') for i,k in enumerate(fields)]
        payload,ledger=apply_spans(q.file.payload,edits);raw=q.file.encode(payload);q=Project(raw);p['indexed_layout_sha256']=layout_digest(q);p['reviewed_resources']['source_payload_sha256']=sha(payload)
        # Scalar replacement sizes shift reviewed bank owners by the exact recorded delta.
        for f in p['reviewed_resources']['frames']:f['header_start']+=sum(len(x.new)-len(x.old) for x in edits if x.end<=f['header_start'])
        s=self.session(raw,p);e=q.element(1,10);spec=dict(version=1,operations=[dict(op='edit_element',page_id=1,element_id=10,expected_element_sha256=element_hash(q,e),states=[dict(value=0,colors=dict(foreground='#123456'))])])
        plan=s.plan_native_update(sha(raw),spec,sha(canonical(spec)));h=plan['plan_sha256'];s.apply_plan(h,h);s.save_as('fg.dpa',sha(s.current));fg=Project((self.root/'fg.dpa').read_bytes())
        self.assertEqual([fg.index.number(fg.element(1,10).states[0],k) for k in fields],list(range(101,108)))
        s.inspect();operations=[dict(op='set_property',page_id=1,element_id=10,state_value=0,field=k,value=0x123456,expected=101+i) for i,k in enumerate(fields)]
        plan=s.plan_changes(operations);h=plan['plan_sha256'];s.apply_plan(h,h);s.save_as('fills.dpa',sha(s.current));final=Project((self.root/'fills.dpa').read_bytes())
        self.assertEqual([final.index.number(final.element(1,10).states[0],k) for k in fields],[0x123456]*7)
        self.assertEqual(final.index.number(final.element(1,10).states[0],'FgFillType'),6)
        self.assertEqual(element_hash(q,q.element(1,11)),element_hash(final,final.element(1,11)))
        s.inspect()
        for value in (True,-1,0x1000000):
            self.refusal('INTEGER',lambda:s.plan_changes([dict(op='set_property',page_id=1,element_id=10,state_value=0,field='FgFillColor',value=value)]))
        self.refusal('PRECONDITION',lambda:s.plan_changes([dict(op='set_property',page_id=1,element_id=10,state_value=0,field='FgFillColor',value=1,expected=999)]))
    def package(self,s):
        p=s.plan_offline_package(sha(s.current),'project.zip','neutral.dpa',dict(ip='0.0.0.0',port=502));return p['plan_sha256']
    def test_package_postwrite_recovery_never_replays(self):
        s=self.session();h=self.package(s);original=artifacts.write_owned
        def loss(journal,oid,path,data):original(journal,oid,path,data);raise OSError('postwrite interruption')
        with patch.object(artifacts,'write_owned',loss):
            with self.assertRaises(OSError):s.apply_offline_package(h,h)
        op=s.inspect_artifact_plan(h)['operation'];self.assertEqual(op['state'],'UNKNOWN_OUTCOME');before=(self.root/'project.zip').read_bytes()
        s=self.session()
        with patch.object(artifacts,'write_owned',side_effect=AssertionError('no replay')):self.assertEqual(s.reconcile_operation(op['operation_id'])['state'],'SUCCEEDED')
        self.assertEqual((self.root/'project.zip').read_bytes(),before);self.refusal('REPLAY_OR_UNKNOWN',lambda:s.apply_offline_package(h,h))
    def test_package_missing_partial_prepared_and_collision_are_not_success(self):
        s=self.session();h=self.package(s);kind,record,data=artifacts.load(s,h)
        op=s.journal.reserve('hmi4artifact:'+h,kind,dict(plan_sha256=h,**record));(self.root/'project.zip').write_bytes(data)
        self.assertEqual(s.reconcile_operation(op)['state'],'UNKNOWN_OUTCOME');(self.root/'project.zip').unlink()
        for label,existing in (('missing',None),('partial',b'partial')):
            p=s.plan_offline_package(sha(s.current),label+'.zip','neutral.dpa',dict(ip='0.0.0.0',port=502));ph=p['plan_sha256'];kind,r,d=artifacts.load(s,ph)
            oid=s.journal.reserve('hmi4artifact:'+ph,kind,dict(plan_sha256=ph,**r));s.journal.transition(oid,'RUNNING')
            if existing is not None:(self.root/(label+'.zip')).write_bytes(existing)
            self.assertEqual(s.reconcile_operation(oid)['state'],'UNKNOWN_OUTCOME')
            self.assertEqual((self.root/(label+'.zip')).exists(),existing is not None)
        p=s.plan_offline_package(sha(s.current),'collision.zip','neutral.dpa',dict(ip='0.0.0.0',port=502));ph=p['plan_sha256']
        def collide(journal,oid,path,data):path.write_bytes(data);raise FileExistsError('another actor won exclusive create')
        with patch.object(artifacts,'write_owned',collide):
            with self.assertRaises(FileExistsError):s.apply_offline_package(ph,ph)
        op=s.inspect_artifact_plan(ph)['operation'];self.assertEqual(op['state'],'FAILED');self.assertEqual(s.reconcile_operation(op['operation_id'])['state'],'FAILED')
    def test_contract_rebind_recovery_and_project_namespace(self):
        a=self.session(path='a.dpa');b=self.session(path='b.dpa');before=dict(schema='delta.native-bindings.v1',tags=[dict(address='D100',type='INT',words=1,access='READ_ONLY')],source_digest='0'*64);after={**before,'source_digest':'1'*64}
        def proposal(s):return s.plan_contract_rebind(sha(s.current),before,sha(canonical(before)),after,sha(canonical(after)))['plan_sha256']
        h=proposal(a);self.assertNotEqual(h,proposal(b));self.refusal('PLAN_SOURCE',lambda:b.apply_contract_rebind(h,h))
        original=a.journal.transition
        def interrupted(oid,state,result=None):
            if state=='SUCCEEDED':raise OSError('receipt response interrupted')
            return original(oid,state,result)
        with patch.object(a.journal,'transition',interrupted):
            with self.assertRaises(OSError):a.apply_contract_rebind(h,h)
        op=a.inspect_artifact_plan(h)['operation'];self.assertEqual(op['state'],'UNKNOWN_OUTCOME')
        a=self.session(path='a.dpa')
        with patch.object(artifacts,'write_owned',side_effect=AssertionError('no native effect')):self.assertEqual(a.reconcile_operation(op['operation_id'])['state'],'SUCCEEDED')
        self.assertEqual((self.root/'a.dpa').read_bytes(),a.source)
        broken={**after,'tags':[dict(address='D100',type='DINT',words=2,access='READ_ONLY')]}
        self.refusal('CONTRACT_SEMANTIC_DRIFT',lambda:a.plan_contract_rebind(sha(a.current),before,sha(canonical(before)),broken,sha(canonical(broken))))
    def test_live_lease_and_changed_source_cannot_reconcile(self):
        s=self.session();h=self.package(s);kind,record,data=artifacts.load(s,h);oid=s.journal.reserve('hmi4artifact:'+h,kind,dict(plan_sha256=h,**record));s.journal.transition(oid,'RUNNING')
        with worker_lease(self.root):self.refusal('OPERATION_LIVE',lambda:s.reconcile_operation(oid))
        (self.root/'source.dpa').write_bytes(s.source+b' ')
        self.refusal('SOURCE_DRIFT',lambda:s.reconcile_operation(oid));self.assertEqual(s.inspect_operation(oid)['state'],'RUNNING')
    def test_new_page_move_clone_and_wrong_navigation_name_refuse(self):
        raw,p=fixture();q=Project(raw)
        base=dict(page_id=1,element_id=10,expected_element_sha256=element_hash(q,q.element(1,10)),new_page_id=3,new_element_id=30,retain_macros=True)
        page=q.page(2);clone=dict(op='clone_page',page_id=2,expected_page_sha256=sha(q.file.payload[page.section.start:page.end]),new_page_id=3,name='Third',retain_macros=False)
        self.assertEqual(len(Project(tx.build(raw,p,dict(version=1,operations=[clone]))['candidate']).pages),3)
        for kind in ('clone_element','move_element'):
            op=dict(op=kind,**base)
            if kind=='clone_element':op['retain_bindings']=True
            spec=dict(version=1,operations=[clone,op]);self.refusal('PAGE_ID',lambda:tx.build(raw,p,spec))
        op=dict(op='navigation',page_id=1,element_id=10,expected_element_sha256=element_hash(q,q.element(1,10)),target_page_id=1,target_name='First')
        self.refusal('NAVIGATION_FAMILY',lambda:tx.build(raw,p,dict(version=1,operations=[op])))
        body=q.file.payload.replace(b'Type=1\r\nSubType=3\r\n',b'Type=1\r\nSubType=10\r\n',1);raw=q.file.encode(body);q=Project(raw)
        p['indexed_layout_sha256']=layout_digest(q);p['reviewed_resources']['source_payload_sha256']=sha(body)
        for f in p['reviewed_resources']['frames']:f['header_start']+=1
        op=dict(op='navigation',page_id=1,element_id=10,expected_element_sha256=element_hash(q,q.element(1,10)),target_page_id=2,target_name='Wrong')
        self.refusal('NAVIGATION_NAME',lambda:tx.build(raw,p,dict(version=1,operations=[op])))
        op.update(target_page_id=1,target_name='First');result=tx.build(raw,p,dict(version=1,operations=[op]));z=Project(result['candidate'])
        self.assertEqual(z.index.scalar(z.element(1,10).section,'GoToScreenName'),'First')
        page=q.page(2);rename=dict(op='edit_page',page_id=2,expected_page_sha256=sha(q.file.payload[page.section.start:page.end]),name='Renamed')
        self.refusal('NAVIGATION_NAME',lambda:tx.build(raw,p,dict(version=1,operations=[rename])))
        op.update(target_page_id=2,target_name='Second')
        self.refusal('NAVIGATION_NAME',lambda:tx.build(raw,p,dict(version=1,operations=[rename,op])))
        op['target_name']='Renamed';renamed=Project(tx.build(raw,p,dict(version=1,operations=[rename,op]))['candidate'])
        from universal_diascreen_hmi.extended.hmi4_inspect import navigation
        edges=navigation(renamed)['edges'];self.assertEqual(len(edges),1);self.assertEqual(edges[0]['name'],'Renamed')
    def test_support_discovery_and_capabilities_share_status(self):
        from universal_diascreen_hmi.extended.transport import install,cli
        from universal_diascreen_hmi.extended.tool_support import registry,UNIMPLEMENTED
        install();listed={t['name']:t for t in cli.tools_list()};s=self.session();support=s.capabilities()['tool_support'];self.assertEqual(set(listed),set(support));self.assertEqual(len(support),83)
        self.assertEqual(support,registry())
