    def test_wide_numeric_enum_writer_and_setvalue_shortcuts_refuse(self):
        from universal_diascreen_hmi.extended.hmi4_inspect import check_binding
        raw,p=fixture();q=Project(raw);e=q.element(1,12)
        edits=[token_patch(q,e.section,k,v,'neutral enum input') for k,v in dict(MemLen=1,MemFmt=1,ReadVar='{Link1}0@D100',WriteVar='{Link1}0@D100').items()]
        body,_=apply_spans(q.file.payload,edits);q=Project(q.file.encode(body));c=dict(tags=[dict(address='D100',type='INT',words=1,access='PARAMETER_EDIT',enum=[0,1])])
        self.refusal('ENUM_INPUT',lambda:check_binding(q,q.element(1,12),c))
        e=q.element(1,12);body,_=apply_spans(q.file.payload,[token_patch(q,e.section,'MaxValue',1,'bounded enum')]);bounded=Project(q.file.encode(body))
        self.assertEqual(check_binding(bounded,bounded.element(1,12),c)['status'],'PASS')
        self.refusal('PROPERTY_NOT_QUALIFIED',lambda:compile_changes(raw,[dict(op='set_property',page_id=1,element_id=10,field='SetValue',value=1)],p))
    def test_xml_update_rechecks_full_member_access_offset_and_array_shape(self):
        from tests.test_symbols import XML
