    def test_native_save_postwrite_loss_recovery_does_not_save_again(self):
        raw,p=fixture();s=self.session(raw,p);proposal=s.plan_changes([dict(op='set_text',page_id=1,element_id=10,state_value=0,text='Changed')]);h=proposal['plan_sha256'];s.apply_plan(h,h)
        original=core.write_owned
        def interrupted(journal,oid,path,data):original(journal,oid,path,data);raise OSError('postwrite failure')
        with patch.object(core,'write_owned',interrupted):
            with self.assertRaises(OSError):s.save_as('candidate.dpa',sha(s.current))
        op=s.journal.find('save:candidate.dpa');self.assertEqual(op['state'],'UNKNOWN_OUTCOME');saved=(self.root/'candidate.dpa').read_bytes()
        fresh=self.session(raw,p);fresh.restore_candidate(h,h)
        with patch.object(core,'write_owned',side_effect=AssertionError('never resave during reconciliation')):
            self.assertEqual(fresh.reconcile_operation(op['operation_id'])['state'],'SUCCEEDED')
        self.assertEqual((self.root/'candidate.dpa').read_bytes(),saved);self.assertEqual((self.root/'source.dpa').read_bytes(),raw)
    def test_running_and_claimed_partial_outputs_never_establish_complete_effect(self):
        s=self.session()
        for mode in ('unclaimed','empty','partial','unfinalized'):
            plan=s.plan_offline_package(sha(s.current),mode+'.zip','neutral.dpa',dict(ip='0.0.0.0',port=502));h=plan['plan_sha256'];kind,record,data=artifacts.load(s,h)
            oid=s.journal.reserve('hmi4artifact:'+h,kind,dict(plan_sha256=h,**record));s.journal.transition(oid,'RUNNING');path=self.root/(mode+'.zip')
            if mode=='unclaimed':path.write_bytes(data)
            else:
                with path.open('xb') as stream:
                    s.journal.claim_output(oid,path,os.fstat(stream.fileno()),data)
                    if mode!='empty':stream.write(data if mode=='unfinalized' else data[:20]);stream.flush();os.fsync(stream.fileno())
            before=path.read_bytes()
            with patch.object(artifacts,'write_owned',side_effect=AssertionError('no retry')):
                self.assertEqual(s.reconcile_operation(oid)['state'],'UNKNOWN_OUTCOME')
            self.assertEqual(path.read_bytes(),before)
    def test_terminal_success_is_historical_when_output_identity_changes(self):
        s=self.session();h=self.package(s);result=s.apply_offline_package(h,h);oid=result['operation_id'];path=self.root/'project.zip';raw=path.read_bytes()
        self.assertEqual(s.reconcile_operation(oid)['state'],'SUCCEEDED')
        path.rename(self.root/'owned-original.zip');path.write_bytes(raw)
        self.refusal('OUTPUT_OWNERSHIP',lambda:s.reconcile_operation(oid))
        self.assertEqual(s.inspect_operation(oid)['state'],'SUCCEEDED');self.assertEqual(path.read_bytes(),raw)
    def test_output_claim_is_bound_to_its_plan_and_rejects_hardlinks(self):
        s=self.session();h=self.package(s);oid=s.apply_offline_package(h,h)['operation_id'];path=self.root/'project.zip'
        with s.journal.connect() as db:
            row=db.execute('SELECT record FROM output_claims WHERE operation_id=?',(oid,)).fetchone();claim=json.loads(row[0]);claim['plan_sha256']='0'*64
            db.execute('UPDATE output_claims SET record=? WHERE operation_id=?',(canonical(claim),oid))
        self.refusal('OUTPUT_OWNERSHIP',lambda:s.reconcile_operation(oid));self.assertEqual(s.inspect_operation(oid)['state'],'SUCCEEDED')
        with s.journal.connect() as db:db.execute('UPDATE output_claims SET record=? WHERE operation_id=?',(row[0],oid))
        os.link(path,self.root/'alias.zip');self.refusal('OUTPUT_FILE',lambda:s.reconcile_operation(oid))
    def test_unexpected_postwrite_error_never_claims_no_effect(self):
        from io import BytesIO
        from universal_diascreen_hmi.extended.transport import cli,install
        install();path=self.root/'effect.dpa';raw,_=fixture()
        class Interrupted:
            def save_as(self,path,candidate_sha256):
                (Path(path)).write_bytes(raw);raise ValueError('unexpected postwrite result failure')
        messages=[dict(jsonrpc='2.0',id=1,method='initialize',params={}),dict(jsonrpc='2.0',id=2,method='tools/call',params=dict(name='save_as',arguments=dict(path=str(path),candidate_sha256=sha(raw))))]
        outgoing=BytesIO();cli.serve(Interrupted(),BytesIO(b''.join(canonical(m)+b'\n' for m in messages)),outgoing)
        reply=json.loads(outgoing.getvalue().splitlines()[-1])['result'];self.assertTrue(reply['isError']);self.assertTrue(path.is_file())
        text=json.loads(reply['content'][0]['text'])['message'];self.assertIn('unverified',text);self.assertNotIn('no write',text)


